(() => {
  'use strict';
  const sessions=new WeakMap();
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const idOf=b=>typeof b.id==='string'&&/^[a-zA-Z0-9_-]{1,128}$/.test(b.id)?encodeURIComponent(b.id):'',tokenOf=b=>b.token||b.coin||{};
  const mainnet=b=>{const t=tokenOf(b);return t.chain==='solana'&&t.cluster==='mainnet-beta'&&t.verified===true&&/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(t.address||'');};
  const action=(name,label,owner)=>owner?`<button class="button" data-builder-action="${name}">${label} ↗</button>`:'';
  function render(build,h={}) {
    if(!idOf(build))return '<main class="rp-release-page"><h1>Game link unavailable</h1><a href="#/">Explore games</a></main>';
    const owner=build.canManage===true,id=idOf(build),name=h.name?.(build)||build.gameName||'Your game',checks=Array.isArray(build.readiness?.checks)?build.readiness.checks.filter(c=>c&&typeof c==='object'):[],review=build.readiness?.readyForCreatorPublish===true,receipt=build.publicationReceipt,uploaded=receipt?.status==='published'&&Number.isSafeInteger(receipt.versionNumber)&&receipt.versionNumber>0;
    return `<main class="rp-release-page"><nav class="rc-breadcrumb"><a href="#/token/${id}">← ${esc(name)}</a><span>CREATOR RELEASE CENTER</span></nav><div class="rc-heading"><span>BUILD → REVIEW → PUBLISH → EARN</span><h1>Your game, your release</h1><p>Each game publishes to its creator’s Roblox account or group Your Solana coin and Roblox experience keep separate ownership and revenue records</p></div>${!owner?'<div class="rc-notice">Public release status · Connect and verify the creator wallet to manage this project '+action(window.RopadSolana?.get?.()?'verify-owner':'wallet',window.RopadSolana?.get?.()?'Verify creator wallet':'Connect creator wallet',true)+'</div>':''}<div class="rc-layout"><section class="rc-steps" aria-label="Game launch checklist"><article class="rc-step"><div class="rc-step-label"><span>01 / GAME QUALITY</span><b>${review?'Review recorded':'Review required'}</b></div><h2>Build something worth playing</h2><p>Inspect the actual Studio game, complete its gameplay loop, and review performance, controls and content</p><ul class="rc-checks">${checks.map(check=>`<li class="${check.passed===true?'passed':''}"><span aria-hidden="true">${check.passed===true?'✓':'○'}</span>${esc(check.label)}</li>`).join('')||'<li>No release checks recorded yet</li>'}</ul><div class="rc-actions"><a class="button" href="#/workspace/${id}">Open creator workspace ↗</a>${action('review','Record release review',owner&&build.status==='ready')}${action('update','Prompt an update',owner)}${action('project-edit','Edit code',owner)}</div><small>Creator reviews are attestations, not automated certification</small></article><article class="rc-step"><div class="rc-step-label"><span>02 / ROBLOX PUBLICATION</span><b>${uploaded?'Version uploaded':'Not uploaded'}</b></div><h2>Publish under your Roblox ownership</h2><p>Create an experience in your own Roblox account or group Connect that project’s publishing permission, review the exact version, and upload it</p>${owner?'<div data-rc-account></div>':''}<div data-rc-publication class="rc-runtime-note">${owner?'Checking this project’s publishing connection':'Publishing connection details are visible to the creator'}</div>${uploaded?`<p>Roblox confirmed version ${receipt.versionNumber} · Public player access still needs checking</p>`:''}<div class="rc-actions">${action('publish','Review Roblox upload',owner)}<a class="button" href="/api/builds/${id}/artifact?format=rbxlx" download>Download project ↓</a><a class="rc-link" href="#/play/${id}">Check play availability ↗</a></div><small>The download contains the saved Ropad project It does not automatically include later manual Studio edits Save those from Studio before publishing</small></article><article class="rc-step"><div class="rc-step-label"><span>03 / SOLANA COIN</span><b>${mainnet(build)?'Mainnet mint verified':tokenOf(build).cluster==='devnet'?'Devnet test coin':'Not launched on mainnet'}</b></div><h2>Launch and verify your coin</h2><p>Review coin creation in your wallet The confirmed mint connects the token page to this game A coin launch does not publish the Roblox experience</p><div data-rc-launch class="rc-runtime-note">Checking the launch network</div><div class="rc-actions">${action('launch','Review coin launch',owner&&!mainnet(build))}<a class="button" href="#/token/${id}">Open token & trading ↗</a></div></article><article class="rc-step"><div class="rc-step-label"><span>04 / CREATOR FEES & COMPUTE</span><b>Separate accounts</b></div><h2>Know where each payment goes</h2><div data-rc-fees class="rc-runtime-note">Checking configured fee policy</div><p>Creator fees are separate from the money buyers spend on the token Review the recipients and percentages before signing a fee-sharing transaction</p><div class="rc-actions">${action('fee-sharing','Inspect creator fees',owner&&mainnet(build))}<a class="button" href="#/workspace/${id}">Inspect AI budget ↗</a></div><small>SOL arriving in a compute treasury is not OpenRouter credit Provider funding must be confirmed before the agent can spend it</small></article></section><aside class="rc-money"><span>HOW CREATORS CAN EARN</span><h2>Two revenue paths</h2><section><b>Roblox game revenue</b><p>Eligible purchases, passes, subscriptions and Creator Rewards are handled by Roblox for the experience owner or group</p><p>Eligible earned Robux can be exchanged through DevEx Roblox currently requires at least 30,000 earned Robux, age 13+, a verified email, good standing and payout approval</p><a href="https://en.help.roblox.com/hc/en-us/articles/203314100-Developer-Exchange-DevEx-Overview-How-to-Submit-Requirements" target="_blank" rel="noopener">DevEx requirements ↗</a></section><section><b>Coin creator fees</b><p>A normal Pump launch assigns its creator fees to the launching wallet An optional Ropad split can divide that creator-fee portion among the creator, platform and AI compute treasury</p><p>Token holders do not automatically own the game or receive its Roblox income Token value and trading gains are not guaranteed earnings</p></section><section><b>Current game monetization</b><p>Generated projects do not yet include a production purchase-receipt system or persistent economy A shop design alone cannot charge players or grant reliable purchases</p><a href="https://create.roblox.com/docs/production/monetization" target="_blank" rel="noopener">Roblox monetization options ↗</a></section><p class="rc-sources-date">Requirements checked October 13, 2026</p></aside></div></main>`;
  }
  async function read(path,signal){const r=await fetch(path,{credentials:'same-origin',signal,headers:{Accept:'application/json'}});if(!r.ok)throw Error('Unavailable');return r.json();}
  function wire(build,root){
    if(!root||!idOf(build))return;const prior=sessions.get(root);prior?.controller.abort();const controller=new AbortController(),state={controller,key:JSON.stringify(build),owner:build.canManage===true};sessions.set(root,state);
    if(prior?.accountRoot)window.RopadRobloxAccount?.unmount(prior.accountRoot);
    state.accountRoot=state.owner?root.querySelector('[data-rc-account]'):null;if(state.accountRoot)window.RopadRobloxAccount?.mount(state.accountRoot);
    const current=()=>root.isConnected!==false&&sessions.get(root)===state;
    const set=(selector,html)=>{if(current()){const slot=root.querySelector(selector);if(slot)slot.innerHTML=html;}};
    read('/api/solana/launches/config',controller.signal).then(config=>set('[data-rc-launch]',config.cluster==='mainnet-beta'&&config.mainnetAvailable===true?'Mainnet launch service selected · Wallet approval and chain confirmation are required':config.cluster==='devnet'?'Devnet mode · Test coins have no real trading revenue':'Launch configuration unavailable · Check again before launching')).catch(()=>set('[data-rc-launch]','Launch configuration unavailable · Check again before launching'));
    read('/api/solana/fees/config',controller.signal).then(config=>{
      if(config.status!=='configured'){set('[data-rc-fees]','Ropad fee recipients and percentages are not configured · No Ropad revenue-sharing policy is active');return;}
      const split=config.splitBps||{},creator=split.creator||0,valid=[split.platform,split.compute,creator].every(n=>Number.isInteger(n)&&n>=0)&&split.platform+split.compute+creator===10000;
      set('[data-rc-fees]',valid?`Configured policy: creator ${creator/100}% · platform ${split.platform/100}% · AI compute ${split.compute/100}%<br>${creator?'The creator recipient comes from the verified launch wallet':'This policy has no separate creator share'}<br>Configuration is not proof that this coin’s on-chain split is active`:'Fee policy could not be validated · Inspect the configuration before signing');
    }).catch(()=>set('[data-rc-fees]','Fee configuration unavailable · No revenue or payout balance can be inferred'));
    if(state.owner)read('/api/builds/'+idOf(build)+'/publication',controller.signal).then(value=>{const c=value.configuration||{};set('[data-rc-publication]',c.connected&&c.configured?`Authorized target: universe ${esc(c.target?.universeId)} · place ${esc(c.target?.placeId)}<br>Upload does not change Roblox public-access settings`:c.connected?'A project target is mapped, but its publishing credential is unavailable':'No creator-owned Roblox destination connected · Keep building or download the project to publish from Studio');}).catch(()=>set('[data-rc-publication]','Publishing status unavailable · Verify the creator wallet and connection'));
  }
  function refresh(build,root,h){const state=sessions.get(root);if(state?.key===JSON.stringify(build))return;state?.controller.abort();const shell=document.createElement('div');shell.innerHTML=render(build,h);root.innerHTML=shell.firstElementChild.innerHTML;wire(build,root);}
  window.RopadReleaseCenter={render,wire,refresh};
})();
